import{_ as a,o as e,c as l,a2 as r}from"./chunks/framework.CdvW4CUT.js";const p=JSON.parse('{"title":"Scala Compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/scala-compatibility.md","filePath":"documentation/scala-compatibility.md","lastUpdated":1793040286000}'),i={name:"documentation/scala-compatibility.md"};function o(d,t,c,s,n,h){return e(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="scala-compatibility" tabindex="-1">Scala Compatibility <a class="header-anchor" href="#scala-compatibility" aria-label="Permalink to &quot;Scala Compatibility&quot;">​</a></h1><h2 id="policy" tabindex="-1">Policy <a class="header-anchor" href="#policy" aria-label="Permalink to &quot;Policy&quot;">​</a></h2><ul><li><strong>Scala 3</strong> artifacts are built against the current <a href="https://scala-lang.org/news/3.9/" target="_blank" rel="noreferrer">Scala 3 LTS</a> line (currently 3.9.x).</li><li><strong>Scala 2.13</strong> artifacts are cross-published and built with the latest Scala 2.13 patch release.</li></ul><h2 id="compatibility-table" tabindex="-1">Compatibility Table <a class="header-anchor" href="#compatibility-table" aria-label="Permalink to &quot;Compatibility Table&quot;">​</a></h2><p>The table shows the Scala version each release was built with. For Scala 3 this is the minimum compiler version your project needs. For Scala 2.13 use the listed patch version or a newer one.</p><table tabindex="0"><thead><tr><th>Version</th><th>Scala 2</th><th>Scala 3</th></tr></thead><tbody><tr><td>3.3.6 and later</td><td>2.13.18</td><td>3.9.0</td></tr><tr><td>3.3.1 - 3.3.5</td><td>2.13.18</td><td>3.10.0</td></tr><tr><td>3.3.0</td><td>2.13.18</td><td>3.9.0</td></tr><tr><td>3.2.0 - 3.2.4</td><td>2.13.18</td><td>3.8.4</td></tr><tr><td>3.1.0 - 3.1.1</td><td>2.13.18</td><td>3.8.3</td></tr><tr><td>3.0.12</td><td>2.13.17</td><td>3.7.2</td></tr><tr><td>3.0.8 - 3.0.11</td><td>2.13.16</td><td>3.7.2</td></tr><tr><td>3.0.4 - 3.0.7</td><td>2.13.16</td><td>3.7.0</td></tr><tr><td>3.0.2 - 3.0.3</td><td>2.13.16</td><td>3.6.4</td></tr><tr><td>3.0.0 - 3.0.1</td><td>2.13.16</td><td>3.6.0</td></tr></tbody></table><p>Versions before 3.0.0 have no Scala 3 support.</p><h2 id="why-we-went-back-from-scala-3-10-to-3-9" tabindex="-1">Why we went back from Scala 3.10 to 3.9 <a class="header-anchor" href="#why-we-went-back-from-scala-3-10-to-3-9" aria-label="Permalink to &quot;Why we went back from Scala 3.10 to 3.9&quot;">​</a></h2><p>Scala 3 is backward compatible, but not forward compatible: a library compiled with Scala 3.x can only be used by projects that compile with Scala 3.x or newer.</p><p>The releases 3.3.1 to 3.3.5 were built with Scala 3.10.0, a Scala Next release. Projects on the Scala 3.9 LTS line could not use these releases.</p><h2 id="scala-2" tabindex="-1">Scala 2 <a class="header-anchor" href="#scala-2" aria-label="Permalink to &quot;Scala 2&quot;">​</a></h2><p>Scala 2 has no LTS line. Scala 2.13 is binary compatible across all 2.13.x patch releases, so we follow the latest 2.13 patch release.</p>',12)])])}const m=a(i,[["render",o]]);export{p as __pageData,m as default};
